from __future__ import annotations
import win32clipboard
def copy_to_clipboard(text: str) -> None: if not text: return win32clipboard.OpenClipboard() try: win32clipboard.EmptyClipboard() win32clipboard.SetClipboardData(win32clipboard.CF_UNICODETEXT, text) finally: win32clipboard.CloseClipboard()

from __future__ import annotations
from app.platform import get_platform_services
def copy_to_clipboard(text: str) -> None: get_platform_services().copy_to_clipboard(text)

from __future__ import annotations

import threading
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from enum import Enum, auto
from typing import Any

try:
    import keyboard
except Exception:  # pragma: no cover - optional at import time
    keyboard = None


class _Phase(Enum):
    IDLE = auto()
    HELD = auto()
    WAITING_NEXT = auto()
    RECORDING = auto()


KEY_MODES: dict[str, str] = {
    "right ctrl": "restructure",
    "right shift": "answer",
}

DOUBLE_PRESS_KEYS = set(KEY_MODES.keys())
TRIPLE_PRESS_RAW_KEYS = {"right ctrl"}


@dataclass
class _KeyState:
    phase: _Phase = _Phase.IDLE
    press_time: float = 0.0
    tap_count: int = 0
    timer: threading.Timer | None = None


@dataclass
class DoublePressHotkeyTracker:
    on_record_start: Callable[[str, str, bool], None]
    on_record_stop: Callable[[float, str, str, bool], None]
    min_hold_seconds: float
    double_press_window_seconds: float = 0.5
    first_press_max_seconds: float = 0.3
    start_delay_seconds: float = 0.2
    on_cancel: Callable[[], None] | None = None

    _keys: dict[str, _KeyState] = field(default_factory=dict)
    _disabled_modes: set[str] = field(default_factory=set)
    _recording_key: str | None = None
    _recording_mode: str = ""
    _recording_output_target: str = ""
    _recording_skip_llm: bool = False
    _record_start_time: float = 0.0
    _recording_started: bool = False
    _hook: Any = None
    _lock: threading.Lock = field(default_factory=threading.Lock)

    def __post_init__(self) -> None:
        for key in DOUBLE_PRESS_KEYS:
            if key not in self._keys:
                self._keys[key] = _KeyState()

    def start(self) -> None:
        if keyboard is None:
            raise RuntimeError("keyboard library is required to capture global hotkeys")
        self._hook = keyboard.hook(self._handle_event)

    def stop(self) -> None:
        with self._lock:
            for ks in self._keys.values():
                self._cancel_key_timer_locked(ks)
                ks.phase = _Phase.IDLE
                ks.press_time = 0.0
                ks.tap_count = 0
            if self._hook is not None and keyboard is not None:
                keyboard.unhook(self._hook)
                self._hook = None
            self._reset_recording_state_locked()

    def _reset_recording_state_locked(self) -> None:
        self._recording_key = None
        self._recording_mode = ""
        self._recording_output_target = ""
        self._recording_skip_llm = False
        self._record_start_time = 0.0
        self._recording_started = False

    def _cancel_key_timer_locked(self, ks: _KeyState) -> None:
        if ks.timer is not None:
            ks.timer.cancel()
            ks.timer = None

    def _handle_event(self, event: Any) -> None:
        name = (event.name or "").lower()
        if name == "backspace" and event.event_type == "down":
            if self.on_cancel is not None:
                self.on_cancel()
            return
        if name not in DOUBLE_PRESS_KEYS:
            return
        mode = KEY_MODES.get(name, "")
        if mode in self._disabled_modes:
            return
        self._process(name, event.event_type, time.monotonic())

    def _process(self, key: str, event_type: str, timestamp: float) -> None:
        start_info: tuple[str, str, bool] | None = None
        stop_info: tuple[float, str, str, bool] | None = None

        with self._lock:
            ks = self._keys.get(key)
            if ks is None:
                return

            if event_type == "down":
                start_info = self._on_key_down_locked(key, ks, timestamp)
            elif event_type == "up":
                stop_info = self._on_key_up_locked(key, ks, timestamp)

        if start_info is not None:
            self.on_record_start(start_info[0], start_info[1], start_info[2])
        if stop_info is not None:
            self.on_record_stop(stop_info[0], stop_info[1], stop_info[2], stop_info[3])

    def _on_key_down_locked(self, key: str, ks: _KeyState, timestamp: float) -> tuple[str, str, bool] | None:
        if ks.phase == _Phase.IDLE:
            ks.phase = _Phase.HELD
            ks.press_time = timestamp
            ks.tap_count = 0
            self._schedule_hold_timer_locked(key, ks)
            return None

        if ks.phase == _Phase.WAITING_NEXT:
            self._cancel_key_timer_locked(ks)
            ks.phase = _Phase.HELD
            ks.press_time = timestamp
            self._schedule_hold_timer_locked(key, ks)

        return None

    def _on_key_up_locked(self, key: str, ks: _KeyState, timestamp: float) -> tuple[float, str, str, bool] | None:
        if ks.phase == _Phase.HELD:
            self._cancel_key_timer_locked(ks)
            hold_time = timestamp - ks.press_time
            if hold_time < self.first_press_max_seconds:
                self._register_tap_locked(key, ks)
            else:
                ks.phase = _Phase.IDLE
                ks.press_time = 0.0
                ks.tap_count = 0
            return None

        if ks.phase == _Phase.RECORDING and key == self._recording_key:
            was_recording = self._recording_started
            rec_mode = self._recording_mode
            output_target = self._recording_output_target
            skip_llm = self._recording_skip_llm
            record_start_time = self._record_start_time
            ks.phase = _Phase.IDLE
            ks.press_time = 0.0
            ks.tap_count = 0
            self._reset_recording_state_locked()
            if was_recording:
                hold_seconds = max(0.0, timestamp - record_start_time)
                return (hold_seconds, rec_mode, output_target, skip_llm)
            return None

        return None

    def _register_tap_locked(self, key: str, ks: _KeyState) -> None:
        ks.press_time = 0.0
        ks.tap_count += 1
        max_taps = 3 if key in TRIPLE_PRESS_RAW_KEYS else 2
        if ks.tap_count >= max_taps:
            ks.phase = _Phase.IDLE
            ks.tap_count = 0
            return

        ks.phase = _Phase.WAITING_NEXT
        timer = threading.Timer(
            self.double_press_window_seconds,
            self._on_tap_timeout,
            args=[key],
        )
        timer.daemon = True
        ks.timer = timer
        timer.start()

    def _schedule_hold_timer_locked(self, key: str, ks: _KeyState) -> None:
        self._cancel_key_timer_locked(ks)
        hold_delay = self._hold_delay_for_tap_count(key, ks.tap_count)
        timer = threading.Timer(hold_delay, self._on_hold_ready, args=[key])
        timer.daemon = True
        ks.timer = timer
        timer.start()

    def _hold_delay_for_tap_count(self, key: str, tap_count: int) -> float:
        if tap_count == 1 and key not in TRIPLE_PRESS_RAW_KEYS:
            return max(0.0, self.start_delay_seconds)
        return max(self.start_delay_seconds, self.first_press_max_seconds)

    def _resolve_hold_action(self, key: str, tap_count: int) -> tuple[str, str, bool] | None:
        if tap_count == 0:
            return (KEY_MODES[key], "both", False)
        if tap_count == 1:
            return (KEY_MODES[key], "clipboard", False)
        if tap_count == 2 and key in TRIPLE_PRESS_RAW_KEYS:
            return (KEY_MODES[key], "both", True)
        return None

    def _start_recording_locked(self) -> tuple[str, str, bool] | None:
        if self._recording_key is None or self._recording_started:
            return None
        self._recording_started = True
        self._record_start_time = time.monotonic()
        return (self._recording_mode, self._recording_output_target, self._recording_skip_llm)

    def _on_hold_ready(self, key: str) -> None:
        start_info: tuple[str, str, bool] | None = None
        with self._lock:
            ks = self._keys.get(key)
            if ks is None:
                return
            ks.timer = None
            if ks.phase != _Phase.HELD:
                return
            action = self._resolve_hold_action(key, ks.tap_count)
            if action is None:
                ks.phase = _Phase.IDLE
                ks.press_time = 0.0
                ks.tap_count = 0
                return
            ks.phase = _Phase.RECORDING
            self._recording_key = key
            self._recording_mode = action[0]
            self._recording_output_target = action[1]
            self._recording_skip_llm = action[2]
            self._record_start_time = 0.0
            self._recording_started = False
            start_info = self._start_recording_locked()
        if start_info is not None:
            self.on_record_start(start_info[0], start_info[1], start_info[2])

    def _on_tap_timeout(self, key: str) -> None:
        with self._lock:
            ks = self._keys.get(key)
            if ks is not None and ks.phase == _Phase.WAITING_NEXT:
                ks.timer = None
                ks.phase = _Phase.IDLE
                ks.tap_count = 0
                ks.press_time = 0.0

    def enable_mode(self, mode: str, enabled: bool) -> None:
        with self._lock:
            if enabled:
                self._disabled_modes.discard(mode)
            else:
                self._disabled_modes.add(mode)
                ks = None
                for k, m in KEY_MODES.items():
                    if m == mode:
                        ks = self._keys.get(k)
                        break
                if ks is not None and ks.phase in (_Phase.HELD, _Phase.WAITING_NEXT):
                    self._cancel_key_timer_locked(ks)
                    ks.phase = _Phase.IDLE
                    ks.tap_count = 0
                    ks.press_time = 0.0

from __future__ import annotations

import threading
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from enum import Enum, auto
from typing import Any

from app.platform import get_platform_services
from app.platform.base import GlobalHotkeyBackend, HotkeyBackendFactory, HotkeyEvent


class _Phase(Enum):
    IDLE = auto()
    HELD = auto()
    WAITING_NEXT = auto()
    RECORDING = auto()


DEFAULT_KEY_MODES: dict[str, str] = {
    "right ctrl": "restructure",
    "right shift": "answer",
}

DEFAULT_TRIPLE_PRESS_RAW_KEYS = {"right ctrl"}


@dataclass
class _KeyState:
    phase: _Phase = _Phase.IDLE
    press_time: float = 0.0
    tap_count: int = 0
    timer: threading.Timer | None = None


@dataclass
class DoublePressHotkeyTracker:
    on_record_start: Callable[[str, str, bool], None]
    on_record_stop: Callable[[float, str, str, bool], None]
    min_hold_seconds: float
    double_press_window_seconds: float = 0.5
    first_press_max_seconds: float = 0.3
    start_delay_seconds: float = 0.2
    on_cancel: Callable[[], None] | None = None
    backend_factory: HotkeyBackendFactory | None = None
    key_modes: dict[str, str] | None = None
    triple_press_raw_keys: set[str] | None = None

    _keys: dict[str, _KeyState] = field(default_factory=dict)
    _disabled_modes: set[str] = field(default_factory=set)
    _recording_key: str | None = None
    _recording_mode: str = ""
    _recording_output_target: str = ""
    _recording_skip_llm: bool = False
    _record_start_time: float = 0.0
    _recording_started: bool = False
    _backend: GlobalHotkeyBackend | None = None
    _lock: threading.Lock = field(default_factory=threading.Lock)

    def __post_init__(self) -> None:
        platform_services = get_platform_services()
        if self.backend_factory is None:
            self.backend_factory = platform_services.create_hotkey_backend
        if self.key_modes is None:
            self.key_modes = dict(platform_services.key_modes)
        if self.triple_press_raw_keys is None:
            self.triple_press_raw_keys = set(platform_services.triple_press_raw_keys)

        for key in self.key_modes or DEFAULT_KEY_MODES:
            if key not in self._keys:
                self._keys[key] = _KeyState()

    def start(self) -> None:
        if self._backend is not None:
            return
        backend_factory = self.backend_factory or get_platform_services().create_hotkey_backend
        backend = backend_factory()
        backend.start(self._handle_event)
        self._backend = backend

    def stop(self) -> None:
        backend = self._backend
        self._backend = None
        with self._lock:
            for ks in self._keys.values():
                self._cancel_key_timer_locked(ks)
                ks.phase = _Phase.IDLE
                ks.press_time = 0.0
                ks.tap_count = 0
            self._reset_recording_state_locked()
        if backend is not None:
            backend.stop()

    def _reset_recording_state_locked(self) -> None:
        self._recording_key = None
        self._recording_mode = ""
        self._recording_output_target = ""
        self._recording_skip_llm = False
        self._record_start_time = 0.0
        self._recording_started = False

    def _cancel_key_timer_locked(self, ks: _KeyState) -> None:
        if ks.timer is not None:
            ks.timer.cancel()
            ks.timer = None

    def _handle_event(self, event: Any) -> None:
        normalized = self._normalize_event(event)
        if normalized is None:
            return
        name, event_type = normalized
        if name == "backspace" and event_type == "down":
            if self.on_cancel is not None:
                self.on_cancel()
            return
        if name not in (self.key_modes or DEFAULT_KEY_MODES):
            return
        mode = (self.key_modes or DEFAULT_KEY_MODES).get(name, "")
        if mode in self._disabled_modes:
            return
        self._process(name, event_type, time.monotonic())

    @staticmethod
    def _normalize_event(event: Any) -> tuple[str, str] | None:
        if isinstance(event, HotkeyEvent):
            name = event.name.lower()
            event_type = event.event_type.lower()
        else:
            name = ((getattr(event, "name", "") or "").lower())
            event_type = str(getattr(event, "event_type", "")).lower()
        if not name or event_type not in {"down", "up"}:
            return None
        return (name, event_type)

    def _process(self, key: str, event_type: str, timestamp: float) -> None:
        start_info: tuple[str, str, bool] | None = None
        stop_info: tuple[float, str, str, bool] | None = None

        with self._lock:
            ks = self._keys.get(key)
            if ks is None:
                return

            if event_type == "down":
                start_info = self._on_key_down_locked(key, ks, timestamp)
            elif event_type == "up":
                stop_info = self._on_key_up_locked(key, ks, timestamp)

        if start_info is not None:
            self.on_record_start(start_info[0], start_info[1], start_info[2])
        if stop_info is not None:
            self.on_record_stop(stop_info[0], stop_info[1], stop_info[2], stop_info[3])

    def _on_key_down_locked(self, key: str, ks: _KeyState, timestamp: float) -> tuple[str, str, bool] | None:
        if ks.phase == _Phase.IDLE:
            ks.phase = _Phase.HELD
            ks.press_time = timestamp
            ks.tap_count = 0
            self._schedule_hold_timer_locked(key, ks)
            return None

        if ks.phase == _Phase.WAITING_NEXT:
            self._cancel_key_timer_locked(ks)
            ks.phase = _Phase.HELD
            ks.press_time = timestamp
            self._schedule_hold_timer_locked(key, ks)

        return None

    def _on_key_up_locked(self, key: str, ks: _KeyState, timestamp: float) -> tuple[float, str, str, bool] | None:
        if ks.phase == _Phase.HELD:
            self._cancel_key_timer_locked(ks)
            hold_time = timestamp - ks.press_time
            if hold_time < self.first_press_max_seconds:
                self._register_tap_locked(key, ks)
            else:
                ks.phase = _Phase.IDLE
                ks.press_time = 0.0
                ks.tap_count = 0
            return None

        if ks.phase == _Phase.RECORDING and key == self._recording_key:
            was_recording = self._recording_started
            rec_mode = self._recording_mode
            output_target = self._recording_output_target
            skip_llm = self._recording_skip_llm
            record_start_time = self._record_start_time
            ks.phase = _Phase.IDLE
            ks.press_time = 0.0
            ks.tap_count = 0
            self._reset_recording_state_locked()
            if was_recording:
                hold_seconds = max(0.0, timestamp - record_start_time)
                return (hold_seconds, rec_mode, output_target, skip_llm)
            return None

        return None

    def _register_tap_locked(self, key: str, ks: _KeyState) -> None:
        ks.press_time = 0.0
        ks.tap_count += 1
        raw_keys = self.triple_press_raw_keys or DEFAULT_TRIPLE_PRESS_RAW_KEYS
        max_taps = 3 if key in raw_keys else 2
        if ks.tap_count >= max_taps:
            ks.phase = _Phase.IDLE
            ks.tap_count = 0
            return

        ks.phase = _Phase.WAITING_NEXT
        timer = threading.Timer(
            self.double_press_window_seconds,
            self._on_tap_timeout,
            args=[key],
        )
        timer.daemon = True
        ks.timer = timer
        timer.start()

    def _schedule_hold_timer_locked(self, key: str, ks: _KeyState) -> None:
        self._cancel_key_timer_locked(ks)
        hold_delay = self._hold_delay_for_tap_count(key, ks.tap_count)
        timer = threading.Timer(hold_delay, self._on_hold_ready, args=[key])
        timer.daemon = True
        ks.timer = timer
        timer.start()

    def _hold_delay_for_tap_count(self, key: str, tap_count: int) -> float:
        raw_keys = self.triple_press_raw_keys or DEFAULT_TRIPLE_PRESS_RAW_KEYS
        if tap_count == 1 and key not in raw_keys:
            return max(0.0, self.start_delay_seconds)
        return max(self.start_delay_seconds, self.first_press_max_seconds)

    def _resolve_hold_action(self, key: str, tap_count: int) -> tuple[str, str, bool] | None:
        key_modes = self.key_modes or DEFAULT_KEY_MODES
        raw_keys = self.triple_press_raw_keys or DEFAULT_TRIPLE_PRESS_RAW_KEYS
        if tap_count == 0:
            return (key_modes[key], "both", False)
        if tap_count == 1:
            return (key_modes[key], "clipboard", False)
        if tap_count == 2 and key in raw_keys:
            return (key_modes[key], "both", True)
        return None

    def _start_recording_locked(self) -> tuple[str, str, bool] | None:
        if self._recording_key is None or self._recording_started:
            return None
        self._recording_started = True
        self._record_start_time = time.monotonic()
        return (self._recording_mode, self._recording_output_target, self._recording_skip_llm)

    def _on_hold_ready(self, key: str) -> None:
        start_info: tuple[str, str, bool] | None = None
        with self._lock:
            ks = self._keys.get(key)
            if ks is None:
                return
            ks.timer = None
            if ks.phase != _Phase.HELD:
                return
            action = self._resolve_hold_action(key, ks.tap_count)
            if action is None:
                ks.phase = _Phase.IDLE
                ks.press_time = 0.0
                ks.tap_count = 0
                return
            ks.phase = _Phase.RECORDING
            self._recording_key = key
            self._recording_mode = action[0]
            self._recording_output_target = action[1]
            self._recording_skip_llm = action[2]
            self._record_start_time = 0.0
            self._recording_started = False
            start_info = self._start_recording_locked()
        if start_info is not None:
            self.on_record_start(start_info[0], start_info[1], start_info[2])

    def _on_tap_timeout(self, key: str) -> None:
        with self._lock:
            ks = self._keys.get(key)
            if ks is not None and ks.phase == _Phase.WAITING_NEXT:
                ks.timer = None
                ks.phase = _Phase.IDLE
                ks.tap_count = 0
                ks.press_time = 0.0

    def enable_mode(self, mode: str, enabled: bool) -> None:
        with self._lock:
            if enabled:
                self._disabled_modes.discard(mode)
            else:
                self._disabled_modes.add(mode)
                ks = None
                for k, m in (self.key_modes or DEFAULT_KEY_MODES).items():
                    if m == mode:
                        ks = self._keys.get(k)
                        break
                if ks is not None and ks.phase in (_Phase.HELD, _Phase.WAITING_NEXT):
                    self._cancel_key_timer_locked(ks)
                    ks.phase = _Phase.IDLE
                    ks.tap_count = 0
                    ks.press_time = 0.0

from __future__ import annotations
from app.platform import get_platform_services
def inject_text(text: str) -> None: get_platform_services().inject_text(text)

from __future__ import annotations
from collections import deque import logging import threading
class InMemoryLogHandler(logging.Handler): def __init__(self, max_entries: int = 1000) -> None: super().__init__() self._entries: deque[str] = deque(maxlen=max_entries) self._lock = threading.Lock()
def emit(self, record: logging.LogRecord) -> None: try: message = self.format(record) except Exception: message = record.getMessage() with self._lock: self._entries.append(message)
def get_entries(self) -> list[str]: with self._lock: return list(self._entries)
def setup_logging(level: str = "INFO") -> logging.Logger: logger = logging.getLogger("dictation") if logger.handlers: return logger
logger.setLevel(getattr(logging, level.upper(), logging.INFO)) formatter = logging.Formatter("%(asctime)s | %(levelname)s | %(message)s")
handler = logging.StreamHandler() handler.setFormatter(formatter) logger.addHandler(handler)
memory_handler = InMemoryLogHandler(max_entries=1000) memory_handler.setFormatter(formatter) logger.addHandler(memory_handler) logger.memory_handler = memory_handler # type: ignore[attr-defined]
logger.propagate = False return logger

from __future__ import annotations
import argparse import queue import threading import time from dataclasses import dataclass from pathlib import Path from typing import Any
import numpy as np
from app.audio import AudioRecorder, rms from app.clipboard import copy_to_clipboard from app.config import AppConfig, load_config from app.hotkeys import DoublePressHotkeyTracker from app.inject import inject_text from app.llm import TranscriptCleaner from app.logger import setup_logging from app.stt import WhisperTranscriber from app.vad import VoiceActivityTrimmer
@dataclass class DictationJob: audio: np.ndarray hold_seconds: float mode: str output_target: str skip_llm: bool = False cancel_generation: int = 0
class DictationApp: def __init__(self, config: AppConfig, base_dir: Path) -> None: self.config = config self.base_dir = base_dir self.logger = setup_logging() self.stop_event = threading.Event() self._llm_recheck_event = threading.Event() self._llm_status_lock = threading.Lock() self._llm_available: bool | None = None self.job_queue: queue.Queue[DictationJob] = queue.Queue(maxsize=1) self._cancel_lock = threading.Lock() self._cancel_generation = 0 self._processing_generation: int | None = None
self.recorder = AudioRecorder(device=config.microphone_device) self.vad = VoiceActivityTrimmer(sample_rate=self.recorder.sample_rate) self.transcriber = WhisperTranscriber( config.whisper_model, config.language_mode, config.whisper_device, config.whisper_compute_type, ) self.cleaner = TranscriptCleaner( base_url=config.vllm_url, model_name=config.model_name, restructure_prompt=config.restructure_prompt, answer_prompt=config.answer_prompt, temperature=config.temperature, max_tokens=config.max_tokens, timeout_seconds=config.llm_timeout_seconds, extra_body=config.llm_extra_body, strict_model_name_match=config.llm_strict_model_name_match, ) self.hotkeys = DoublePressHotkeyTracker( on_record_start=self._on_record_start, on_record_stop=self._on_record_stop, on_cancel=self._on_cancel_requested, min_hold_seconds=config.min_hold_seconds, start_delay_seconds=config.record_start_delay_seconds, double_press_window_seconds=config.double_press_window_seconds, first_press_max_seconds=config.first_press_max_seconds, ) self.worker = threading.Thread(target=self._worker_loop, daemon=True) self.llm_monitor = threading.Thread(target=self._llm_monitor_loop, daemon=True)
def run(self) -> None: self.logger.info("Starting dictation assistant") self.worker.start() self.llm_monitor.start() self.hotkeys.start()
while not self.stop_event.is_set(): time.sleep(0.1)
self.hotkeys.stop()
def shutdown(self) -> None: self.logger.info("Shutting down dictation assistant") self.stop_event.set() self._llm_recheck_event.set()
def update_llm_endpoint(self, base_url: str) -> None: self.config.vllm_url = base_url self.cleaner.client.base_url = base_url with self._llm_status_lock: self._llm_available = None self._llm_recheck_event.set()
def update_llm_settings( self, extra_body: dict[str, Any] | None, strict_model_name_match: bool, ) -> None: self.config.llm_extra_body = extra_body self.config.llm_strict_model_name_match = strict_model_name_match self.cleaner.extra_body = extra_body self.cleaner.strict_model_name_match = strict_model_name_match with self._llm_status_lock: self._llm_available = None self._llm_recheck_event.set()
def _on_record_start(self, mode: str, output_target: str, skip_llm: bool) -> None: self.logger.info( "Recording started (mode: %s, output: %s, skip_llm: %s)", mode, output_target, skip_llm, ) try: self.recorder.start() except Exception as exc: self.logger.exception("Failed to start recording: %s", exc)
def _on_record_stop(self, hold_seconds: float, mode: str, output_target: str, skip_llm: bool) -> None: self.logger.info( "Recording stopped, hold %.2fs (mode: %s, output: %s, skip_llm: %s)", hold_seconds, mode, output_target, skip_llm, ) audio = self.recorder.stop()
if hold_seconds < self.config.min_hold_seconds: self.logger.info("Ignored: hold shorter than %.2fs", self.config.min_hold_seconds) return
if audio.size == 0 or rms(audio) < self.config.silence_rms_threshold: self.logger.info("Ignored: empty/silent audio") return
if self.config.debug_save_wav: stamp = time.strftime("%Y%m%d-%H%M%S", time.localtime()) debug_path = self.base_dir / self.config.debug_wav_dir / f"capture-{stamp}.wav" self.recorder.save_wav(audio, debug_path)
job = DictationJob( audio=audio, hold_seconds=hold_seconds, mode=mode, output_target=output_target, skip_llm=skip_llm, cancel_generation=self._get_cancel_generation(), ) try: self.job_queue.put_nowait(job) except queue.Full: try: self.job_queue.get_nowait() except queue.Empty: pass try: self.job_queue.put_nowait(job) self.logger.warning( "Replaced queued recording: pipeline busy (transcription/LLM still running)" ) except queue.Full: self.logger.warning("Dropped recording: pipeline busy")
def _get_cancel_generation(self) -> int: with self._cancel_lock: return self._cancel_generation
def _is_cancelled(self, job: DictationJob) -> bool: return job.cancel_generation != self._get_cancel_generation()
def _set_processing_generation(self, generation: int | None) -> None: with self._cancel_lock: self._processing_generation = generation
def _on_cancel_requested(self) -> None: drained = 0 with self._cancel_lock: self._cancel_generation += 1 processing = self._processing_generation is not None
while True: try: self.job_queue.get_nowait() drained += 1 except queue.Empty: break
if processing or drained: self.logger.info( "Cancellation requested via Backspace (processing=%s, dropped_queued_jobs=%d)", processing, drained, )
def _worker_loop(self) -> None: while not self.stop_event.is_set(): try: job = self.job_queue.get(timeout=0.1) except queue.Empty: continue
try: self._process_job(job) except Exception as exc: self.logger.exception("Pipeline error: %s", exc)
def _llm_monitor_loop(self) -> None: while not self.stop_event.is_set(): if self._get_llm_available() is True: self._llm_recheck_event.wait(timeout=0.5) self._llm_recheck_event.clear() continue
self._check_llm_availability() if self.stop_event.is_set(): return if self._get_llm_available() is True: continue if self.stop_event.wait(timeout=self.config.llm_availability_check_interval_seconds): return
def _get_llm_available(self) -> bool | None: with self._llm_status_lock: return self._llm_available
def _set_llm_available(self, available: bool) -> bool | None: with self._llm_status_lock: previous = self._llm_available self._llm_available = available
if not available and previous is not False: self._llm_recheck_event.set() return previous
def _check_llm_availability(self) -> bool: try: available = self.cleaner.is_model_available() except Exception as exc: self._set_llm_available(False) self.logger.warning( "LLM server unavailable (%s); retrying in %.1fs", exc, self.config.llm_availability_check_interval_seconds, ) return False
previous = self._set_llm_available(available) if available: if previous is not True: self.logger.info("LLM model is available again") return True
self.logger.warning( "Configured LLM model '%s' is unavailable; retrying in %.1fs", self.config.model_name, self.config.llm_availability_check_interval_seconds, ) return False
def _process_job(self, job: DictationJob) -> None: if self._is_cancelled(job): self.logger.info("Skipped job: cancelled before processing started") return
self._set_processing_generation(job.cancel_generation) self.logger.info( "Processing recording (mode: %s, output: %s, skip_llm: %s)", job.mode, job.output_target, job.skip_llm, )
try: audio = job.audio pcm16 = AudioRecorder.to_pcm16(audio) if self.config.vad_enabled: trimmed = self.vad.trim(pcm16) if trimmed.size == 0: self.logger.info("Ignored: VAD detected silence") return audio = (trimmed.astype(np.float32) / 32767.0).clip(-1.0, 1.0)
if self._is_cancelled(job): self.logger.info("Cancelled before transcription completed") return
self.logger.info("Transcribing audio (%.1fs)...", job.hold_seconds) transcript = self.transcriber.transcribe(audio, sample_rate=self.recorder.sample_rate) if self._is_cancelled(job): self.logger.info("Cancelled after transcription; dropping result") return if not transcript: self.logger.info("Ignored: empty transcription") return
self.logger.info("Raw transcript: %s", transcript) result = self._transform_transcript(transcript, mode=job.mode, skip_llm=job.skip_llm) if self._is_cancelled(job): self.logger.info("Cancelled after transformation; not delivering output") return
if result: self._deliver_result(result, output_target=job.output_target) finally: self._set_processing_generation(None)
def _transform_transcript(self, transcript: str, mode: str, skip_llm: bool = False) -> str: if skip_llm: self.logger.info("Skipping LLM and using raw transcript for fast clipboard output") return transcript
if self._get_llm_available() is not True: self.logger.info("Skipping LLM because the last availability check reported it unavailable") return transcript
language = getattr(getattr(self, "transcriber", None), "last_language", None) self.logger.info("Sending transcript to LLM (%s)...", self.config.vllm_url) try: if mode == "answer": candidate = self.cleaner.answer(transcript, language=language) else: candidate = self.cleaner.clean(transcript, language=language) except Exception as exc: self.logger.warning("LLM request failed, using raw transcript until recovery check succeeds: %s", exc) self._set_llm_available(False) return transcript
if not candidate or not candidate.strip(): self.logger.warning("LLM returned an empty response, using raw transcript") return transcript
candidate = candidate.strip() self._set_llm_available(True) self.logger.info("LLM response received (%d characters)", len(candidate)) return candidate
def _deliver_result(self, result: str, output_target: str) -> None: if output_target in ("insert", "both"): try: inject_text(result) self.logger.info("Inserted %d characters into the active field", len(result)) except Exception as exc: self.logger.warning("Text insertion failed: %s", exc) if output_target == "insert": copy_to_clipboard(result) self.logger.info("Copied %d characters to clipboard after insert failure", len(result))
if output_target in ("clipboard", "both"): copy_to_clipboard(result) self.logger.info("Copied %d characters to clipboard", len(result))
def parse_args() -> argparse.Namespace: parser = argparse.ArgumentParser(description="Local push-to-talk dictation assistant (system tray app)") parser.add_argument( "--config", default="config.json", help="Path to JSON config file", ) return parser.parse_args()
def main() -> None: args = parse_args() config_path = Path(args.config).resolve()
logger = setup_logging() logger.info("Launching tray UI; look for the microphone icon in the Windows notification area.")
from app.tray import TrayApp tray = TrayApp(config_path=config_path) tray.run()
if __name__ == "__main__": main()

